#include <iostream>
using namespace std;
bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)   // 试到 sqrt(n) 就够了
        if (n % i == 0) return false;
    return true;
}
int main() {
    int n;
    cin >> n;
    cout << (isPrime(n) ? "是素数" : "不是素数") << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;
int a[105], b[105], c[105];
int main() {
    string s1, s2;
    cin >> s1 >> s2;
    for (int i = 0; i < s1.size(); i++) a[s1.size()-1-i] = s1[i]-'0';
    for (int i = 0; i < s2.size(); i++) b[s2.size()-1-i] = s2[i]-'0';
    int len = max(s1.size(), s2.size());
    for (int i = 0; i < len; i++) {
        c[i] += a[i] + b[i];
        if (c[i] >= 10) { c[i+1]++; c[i] -= 10; }  // 进位
    }
    if (c[len]) len++;
    for (int i = len-1; i >= 0; i--) cout << c[i];
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;
struct Node {
    int val;
    Node* next;
};
int main() {
    Node a, b, c;
    a.val = 1; b.val = 2; c.val = 3;
    a.next = &b; b.next = &c; c.next = nullptr;
    for (Node* p = &a; p != nullptr; p = p->next)
        cout << p->val << " ";   // 1 2 3
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;
int gcd(int a, int b) {           // 辗转相除法
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int main() {
    int a, b;
    cin >> a >> b;
    cout << gcd(a, b) << endl;
    return 0;
}

#include <iostream>
using namespace std;
int a[100005];
int main() {
    int n, x;
    cin >> n >> x;
    for (int i = 0; i < n; i++) cin >> a[i];
    int l = 0, r = n - 1, ans = -1;
    while (l <= r) {
        int mid = (l + r) / 2;
        if (a[mid] >= x) { ans = mid; r = mid - 1; }  // 第一个 >= x 的位置
        else l = mid + 1;
    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
using namespace std;
int fact(int n) {
    if (n <= 1) return 1;       // 出口
    return n * fact(n - 1);     // 自己调用自己
}
int main() {
    int n;
    cin >> n;
    cout << fact(n) << endl;
    return 0;
}

